(1, 1, 1, 'LEAVE_APPLICATION_SMS_NOTIFICATION', '<h1>Leave Application Notification</h1>\n\n\n\n<h3>Details:</h3>\n\n\n\n<table>\n\n	<tbody>\n\n		<tr>\n\n			<td data-row="1">Employee :</td>\n\n			<td data-row="1">{{employee_name}}</td>\n\n		</tr>\n\n		<tr>\n\n			<td data-row="2">Leave Type :</td>\n\n			<td data-row="2">{{leave_type}}</td>\n\n		</tr>\n\n		<tr>\n\n			<td data-row="3">From Date :</td>\n\n			<td data-row="3">{{from_date}}</td>\n\n		</tr>\n\n		<tr>\n\n			<td data-row="4">To Date :</td>\n\n			<td data-row="4">{{to_date}}</td>\n\n		</tr>\n\n		<tr>\n\n			<td data-row="5">Leave Status :</td>\n\n			<td data-row="5">{{status}}</td>\n\n		</tr>\n\n		<tr>\n\n			<td data-row="5">Leave Reason :</td>\n\n			<td data-row="5">{{reason}}</td>\n\n		</tr>\n\n	</tbody>\n\n</table>\n\n<br />\n\nThanks\n\n<h1>Â </h1>\n\n', 'sms_document_attachment_9701538.xls', '2020-11-02 12:27:51', '2020-11-02 12:52:30', 0),
